import {Chess} from './vendor/chess.js';
import {playUci} from './tactics.js';
const text=(s,max=300)=>typeof s==='string'&&s.length>0&&s.length<=max;
const number=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;
export function validateBackup(data){if(data?.format!=='plystreak-backup'||data.version!==1||!Array.isArray(data.games)||data.games.length>50000)throw Error('Formato backup non valido.');const games=data.games.map(g=>{if(!text(g.id)||!text(g.pgn,1000000))throw Error('Partita nel backup non valida.');const c=new Chess();c.loadPgn(g.pgn);const moves=c.history({verbose:true});let analysis;
 if(g.analysis?.version===2&&Array.isArray(g.analysis.details)){const used=new Set();const details=g.analysis.details.map(d=>{const m=moves[d.ply];if(!m||used.has(d.ply)||!number(d.accuracy,0,100)||!number(d.loss,0,1)||d.fen!==m.before||d.afterFen!==m.after||d.side!==m.color)throw Error('Analisi nel backup incoerente con la partita.');used.add(d.ply);const best=playUci(new Chess(m.before),d.best)?d.best:undefined;return {ply:d.ply,side:m.color,san:m.san,from:m.from,to:m.to,promotion:m.promotion,fen:m.before,afterFen:m.after,loss:d.loss,accuracy:d.accuracy,type:text(d.type,25)?d.type:'good',theme:['king','fork','pin','hanging','material','position'].includes(d.theme)?d.theme:'position',best}});const expected=g.analysis.coverage==='player'?moves.filter(m=>m.color===g.side):moves;analysis={version:2,details,complete:!!g.analysis.complete&&expected.every(m=>details.some(d=>d.ply===moves.indexOf(m))),coverage:g.analysis.coverage==='player'?'player':'all',at:number(g.analysis.at,0,8640000000000000)?g.analysis.at:Date.now()}}
 return {id:g.id,pgn:g.pgn,source:['coach','chess.com','import'].includes(g.source)?g.source:'import',side:['w','b'].includes(g.side)?g.side:null,playedAt:number(g.playedAt,0,8640000000000000)?g.playedAt:Date.now(),analysis}});
 if(data.attempts!==undefined&&!Array.isArray(data.attempts))throw Error('Ripassi nel backup non validi.');const attempts=(data.attempts||[]).map(a=>{if(!text(a.id)||!number(a.at,0,8640000000000000)||typeof a.success!=='boolean')throw Error('Tentativo nel backup non valido.');return {id:a.id,cardId:text(a.cardId)?a.cardId:undefined,sessionId:text(a.sessionId)?a.sessionId:undefined,position:text(a.position)?a.position:'',theme:text(a.theme,25)?a.theme:'position',success:a.success,assisted:!!a.assisted,at:a.at}});return {games,attempts}}
